window.addEventListener("resize", resize);
resize();
resetSeeds();

function onMove(cx, cy) {
  var nx = cx / Math.max(1, window.innerWidth);
  var ny = cy / Math.max(1, window.innerHeight);
  nx = Math.min(1, Math.max(0, nx)); ny = Math.min(1, Math.max(0, ny));
  mouse.vx = nx - mouse.tx; mouse.vy = ny - mouse.ty;
  mouse.tx = nx; mouse.ty = ny; mouse.active = true;
  glowTarget = Math.min(1, Math.abs(mouse.vx) * 30 + Math.abs(mouse.vy) * 30);
  if (!reduceMotion && ripples.length < 6 && Math.hypot(mouse.vx, mouse.vy) > 0.004) {
    ripples.push({ r: 10 * S, alpha: 0.35 });
  }
}
window.addEventListener("pointermove", function (e) { onMove(e.clientX, e.clientY); }, { passive: true });
window.addEventListener("pointerdown", function (e) {
  onMove(e.clientX, e.clientY);
  if (!reduceMotion) { ripples.push({ r: 6 * S, alpha: 0.6 }); ripples.push({ r: 2 * S, alpha: 0.4 }); }
}, { passive: true });
window.addEventListener("touchmove", function (e) {
  if (e.touches.length) onMove(e.touches[0].clientX, e.touches[0].clientY);
}, { passive: true });

function bg() {
  var g = ctx.createRadialGradient(CX, CY - 120 * S, 40 * S, CX, CY - 60 * S, Math.max(W, H) * 0.85);
  g.addColorStop(0, "#241610");
  g.addColorStop(0.28, "#150e0a");
  g.addColorStop(0.6, "#0a0806");
  g.addColorStop(1, "#040303");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  // distant warm halo behind bowl
  var haloX = CX + (mouse.x - 0.5) * 40 * S;
  var haloY = CY - 150 * S + (mouse.y - 0.5) * 24 * S;
  var haloR = 300 * S * (1 + glowFlicker * 0.06);
  var hg = ctx.createRadialGradient(haloX, haloY, 10, haloX, haloY, haloR);
  hg.addColorStop(0, "rgba(255,138,54," + (0.20 + glowFlicker * 0.05) + ")");
  hg.addColorStop(0.5, "rgba(150,60,20,0.08)");
  hg.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = hg;
  ctx.fillRect(0, 0, W, H);
  // table
  var tg = ctx.createLinearGradient(0, CY, 0, H);
  tg.addColorStop(0, "#100b08");
  tg.addColorStop(0.25, "#17100b");
  tg.addColorStop(1, "#050403");
  ctx.fillStyle = tg;
  ctx.fillRect(0, CY + 60 * S, W, H - CY);
  // table sheen under bowl
  var sh = ctx.createRadialGradient(CX, CY + 170 * S, 10, CX, CY + 170 * S, 340 * S);
  sh.addColorStop(0, "rgba(255,150,70,0.10)");
  sh.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = sh;
  ctx.fillRect(0, 0, W, H);
}

